function dismissOAPLoader() {
    console.log("OAP: dismissOAPLoader called");

    const shadowHost = document.documentElement.querySelectorAll("#bg-oap-loader");
    if (shadowHost.length > 0) {
        for (let i = 0; i < shadowHost.length; i++) {
            shadowHost[i].remove();
        }
    } else {
        console.log("OAP: dismissOAPLoader: shadowHost not found");
    }
}

